class Solution {
public:
    vector<long long> kthPalindrome(vector<int>& queries, int intLength) {
        int half = (intLength + 1) / 2;
        long long base = 1;
        for (int i = 1; i < half; i++) base *= 10;
        long long limit = base * 10;

        vector<long long> answer;
        answer.reserve(queries.size());
        for (int q : queries) {
            long long firstHalf = base + (long long)(q - 1);
            if (firstHalf >= limit) {
                answer.push_back(-1);
                continue;
            }
            long long rev = 0;
            long long tmp = (intLength % 2 == 0) ? firstHalf : firstHalf / 10;
            while (tmp > 0) {
                rev = rev * 10 + tmp % 10;
                tmp /= 10;
            }
            long long mul = (intLength % 2 == 0) ? limit : base;
            answer.push_back(firstHalf * mul + rev);
        }
        return answer;
    }
};
